import { useState } from "react";
import { Stack } from "@/shared/ui/layout/Stack";
import { Row } from "@/shared/ui/layout/Row";
import { Box } from "@/shared/ui/layout/Box";
import { Text } from "@/shared/ui/typography/Text";
import { Code } from "@/shared/ui/data/Code";

// Vendored from `../lib/toolPresets` (unresolvable in this sandbox) — unchanged.
const TOOL_PRESETS = [
  { label: "read-only", allow: ["Read", "Glob", "Grep"], deny: ["Write", "Edit", "MultiEdit", "Bash", "WebFetch", "WebSearch"] },
  { label: "no-bash", allow: [], deny: ["Bash"] },
  { label: "no-web", allow: [], deny: ["WebFetch", "WebSearch"] },
  { label: "full", allow: [], deny: [] },
];
const COMMON_TOOLS = ["Read", "Write", "Edit", "MultiEdit", "Bash", "Glob", "Grep", "WebFetch", "WebSearch"];

// Vendored from `../ToolPermissionInputs` (unresolvable in this sandbox) — unchanged.
function ToolChip({ label, onRemove }) {
  return (
    <Box as="span" className="mono" pad={[2, 8]} bg="var(--bg-elev)" border="soft" radius={4} style={{
      display: "inline-flex", alignItems: "center", gap: 4,
      fontSize: 10.5, color: "var(--fg-muted)",
    }}>
      {label}
      <Text as="span" tone="dim" onClick={onRemove} style={{ cursor: "pointer", lineHeight: 1 }}>×</Text>
    </Box>
  );
}
function ChipInput({ value, onChange, onAdd, placeholder }) {
  return (
    <Row gap={5}>
      {/* eslint-disable-next-line no-restricted-syntax -- bespoke inline datalist-backed entry (fixed width/height) beside a custom "+ add"; a TextField .field wrapper would break the Row */}
      <input
        className="input mono"
        value={value}
        onChange={(e) => onChange(e.target.value)}
        onKeyDown={(e) => { if (e.key === "Enter") { e.preventDefault(); onAdd(); } }}
        placeholder={placeholder}
        list="tool-suggestions"
        style={{ width: 130, height: 24, padding: "0 8px", fontSize: 10.5 }}
      />
      <datalist id="tool-suggestions">
        {COMMON_TOOLS.map((t) => <option key={t} value={t} />)}
      </datalist>
      <Box as="span" className="mono" onClick={onAdd} pad={[2, 8]} bg="var(--bg-elev)" border="soft" radius={4} style={{ cursor: "pointer",
        fontSize: 10.5, color: "var(--fg-muted)",
      }}>+ add</Box>
    </Row>
  );
}

export function ToolPermissionsPanel({
  allow: allowProp, setAllow: setAllowProp, deny: denyProp, setDeny: setDenyProp,
  allowInput: allowInputProp, setAllowInput: setAllowInputProp, denyInput: denyInputProp, setDenyInput: setDenyInputProp,
  applyPreset: applyPresetProp, addToAllow: addToAllowProp, addToDeny: addToDenyProp,
}) {
  const [localAllow, setLocalAllow] = useState(["Read", "Glob", "Grep"]);
  const [localDeny, setLocalDeny] = useState(["Bash"]);
  const [localAllowInput, setLocalAllowInput] = useState("");
  const [localDenyInput, setLocalDenyInput] = useState("");

  const allow = allowProp ?? localAllow;
  const setAllow = setAllowProp ?? setLocalAllow;
  const deny = denyProp ?? localDeny;
  const setDeny = setDenyProp ?? setLocalDeny;
  const allowInput = allowInputProp ?? localAllowInput;
  const setAllowInput = setAllowInputProp ?? setLocalAllowInput;
  const denyInput = denyInputProp ?? localDenyInput;
  const setDenyInput = setDenyInputProp ?? setLocalDenyInput;
  const applyPreset = applyPresetProp ?? ((p) => { setAllow(p.allow); setDeny(p.deny); });
  const addToAllow = addToAllowProp ?? (() => { const v = allowInput.trim(); if (v && !allow.includes(v)) setAllow((a) => [...a, v]); setAllowInput(""); });
  const addToDeny = addToDenyProp ?? (() => { const v = denyInput.trim(); if (v && !deny.includes(v)) setDeny((d) => [...d, v]); setDenyInput(""); });

  return (
    <Box bg="var(--bg-panel)" border="soft" radius={8} style={{
      overflow: "hidden",
    }}>
      <Box className="mono" pad={[8, 14]} bg="var(--bg-elev)" style={{ borderBottom: "1px solid var(--border-soft)",
        fontSize: 10,
        color: "var(--fg-dim)", textTransform: "uppercase", letterSpacing: ".06em",
      }}>
        Tool permissions
      </Box>
      <Stack gap={16} style={{ padding: "14px 14px" }}>
        <Box>
          <Text as="div" mono size={9.5} tone="dim" style={{ marginBottom: 7, textTransform: "uppercase", letterSpacing: ".06em" }}>quick presets</Text>
          <Row gap={5} align="stretch" wrap>
            {TOOL_PRESETS.map((p) => (
              <Box
                as="span"
                key={p.label}
                className="mono"
                onClick={() => applyPreset(p)}
                pad={[2, 8]} bg="var(--bg-elev)" border="soft" radius={4} style={{ cursor: "pointer",
                  fontSize: 10,
                  color: "var(--fg-muted)",
                }}
              >{p.label}</Box>
            ))}
          </Row>
        </Box>

        <Box>
          <Text as="div" mono size={9.5} tone="success" style={{ marginBottom: 7, textTransform: "uppercase", letterSpacing: ".06em" }}>allow</Text>
          <Row gap={5} align="stretch" wrap style={{ marginBottom: 8 }}>
            {allow.length === 0 && (
              <Text as="span" mono size={10.5} tone="dim" style={{ fontStyle: "italic" }}>all tools allowed</Text>
            )}
            {allow.map((t) => (
              <ToolChip key={t} label={t} onRemove={() => setAllow((a) => a.filter((x) => x !== t))} />
            ))}
          </Row>
          <ChipInput value={allowInput} onChange={setAllowInput} onAdd={addToAllow} placeholder="tool name..." />
        </Box>

        <Box>
          <Text as="div" mono size={9.5} tone="danger" style={{ marginBottom: 7, textTransform: "uppercase", letterSpacing: ".06em" }}>deny</Text>
          <Row gap={5} align="stretch" wrap style={{ marginBottom: 8 }}>
            {deny.length === 0 && (
              <Text as="span" mono size={10.5} tone="dim" style={{ fontStyle: "italic" }}>nothing denied</Text>
            )}
            {deny.map((t) => (
              <ToolChip key={t} label={t} onRemove={() => setDeny((d) => d.filter((x) => x !== t))} />
            ))}
          </Row>
          <ChipInput value={denyInput} onChange={setDenyInput} onAdd={addToDeny} placeholder="tool name..." />
        </Box>

        {(allow.length > 0 || deny.length > 0) && (
          <Code wrap={false} tone="dim" style={{ fontSize: 9.5, padding: "10px 12px", borderRadius: 6 }}>
            {JSON.stringify({ permissions: { allow, deny } }, null, 2)}
          </Code>
        )}
      </Stack>
    </Box>
  );
}
